#!/usr/bin/env python3
"""CC-11 directed strict OAS 3.0.3 check (read-only).

Purpose: independently prove that, under STRICT OAS 3.0.3 -> JSON Schema
semantics, the 13 CC-11 contract-modeling defects are fixed in the patched
openapi.yaml, AND that the SAME script reproduces the original defects on the
pre-fix openapi.yaml (so it discriminates rather than vacuously passing).

Strict semantics implemented here (aligned with the documented RV-6 converter,
but implemented independently so it does not import E's driver):
  * ``nullable`` unions ``null`` ONLY when the SAME Schema Object declares a
    local ``type`` (string or list); with ``$ref``/``allOf`` it has NO effect.
  * ``allOf`` is NOT flattened: each conjunct is validated natively, so a
    conjunct's ``additionalProperties:false`` cannot see sibling conjunct
    properties (the exact A08 ProgressWithSync defect).

For each allowlisted (API, instance-path) it locates the field's schema by
navigating the ACTUAL response schema (through $ref/allOf/items) and validates
``null`` against it. A08 additionally validates a full ``data`` object that
carries ``lastSyncedAt`` (the additionalProperties defect).

Usage: python cc11_directed_strict_check.py <openapi.yaml>
Exit 0 iff all 13 expectations hold (post-fix mode); --expect-defects flips the
expectation to require the OLD breakage (used on the pre-fix YAML).
"""
from __future__ import annotations

import sys
from typing import Any

import yaml
from jsonschema import Draft202012Validator

# (api, normalized instance path) for the 12 nullable paths + the A08 object case
NULLABLE_CASES = [
    ("A01", "$.data.items[*].progress.completedAt"),
    ("A02", "$.data.progress.completedAt"),
    ("A03", "$.data.controller.gimbalId"),
    ("A03", "$.data.progress.completedAt"),
    ("A03", "$.data.verification.validUntil"),
    ("A04", "$.data.progress.completedAt"),
    ("A04", "$.data.verification.validUntil"),
    ("A05", "$.data.progress.completedAt"),
    ("A07", "$.data.controller.gimbalId"),
    ("A07", "$.data.progress.completedAt"),
    ("A08", "$.data.completedAt"),
    ("A09", "$.data.items[*].closedAt"),
]
A08_OBJECT_PATH = "$.data"  # ProgressWithSync structure (lastSyncedAt union)

# API -> (path, method, success status) as referenced by E's CC-11 allowlist
API_ENDPOINT = {
    "A01": ("/api/v1/members/{memberId}/care-plans", "get", "200"),
    "A02": ("/api/v1/care-plans/{planId}", "get", "200"),
    "A03": ("/api/v1/care-executions", "post", "201"),
    "A04": ("/api/v1/care-executions/{executionId}/revalidations", "post", "200"),
    "A05": ("/api/v1/care-executions/{executionId}/observations", "post", "200"),
    "A07": ("/api/v1/care-executions/{executionId}", "get", "200"),
    "A08": ("/api/v1/care-plans/{planId}/progress", "get", "200"),
    "A09": ("/api/v1/members/{memberId}/care-executions", "get", "200"),
}


def resolve_pointer(doc: Any, ref: str) -> Any:
    node = doc
    for part in ref[2:].split("/"):
        node = node[part.replace("~1", "/").replace("~0", "~")]
    return node


def strict_convert(node: Any, doc: Any, seen: tuple[str, ...] = ()) -> Any:
    """OAS 3.0.3 -> JSON Schema 2020-12 under strict nullable semantics."""
    if isinstance(node, bool) or not isinstance(node, dict):
        return node
    ref = node.get("$ref")
    if isinstance(ref, str):
        if ref in seen:
            raise ValueError(f"cyclic $ref: {ref}")
        target = strict_convert(resolve_pointer(doc, ref), doc, seen + (ref,))
        siblings = {k: v for k, v in node.items() if k != "$ref"}
        if not siblings:
            return target
        return {"allOf": [target, strict_convert(siblings, doc, seen)]}

    out: dict = {}
    nullable = node.get("nullable") is True
    for key, value in node.items():
        if key == "nullable":
            continue
        if key == "properties":
            out[key] = {pk: strict_convert(pv, doc, seen) for pk, pv in value.items()}
        elif key == "items":
            out[key] = strict_convert(value, doc, seen)
        elif key == "additionalProperties":
            out[key] = strict_convert(value, doc, seen) if isinstance(value, dict) else value
        elif key in ("allOf", "oneOf", "anyOf"):
            out[key] = [strict_convert(x, doc, seen) for x in value]
        elif key == "not":
            out[key] = strict_convert(value, doc, seen)
        else:
            out[key] = value

    if nullable:
        declared = out.get("type")
        if isinstance(declared, str):
            out["type"] = [declared, "null"]
        elif isinstance(declared, list) and "null" not in declared:
            out["type"] = declared + ["null"]
        # else: no local type -> nullable is a NO-OP (strict 3.0.3)
    return out


def conjuncts(node: Any, doc: Any) -> list[dict]:
    """All schema objects conjoined at this position (resolve $ref, expand allOf)."""
    node = node
    while isinstance(node, dict) and isinstance(node.get("$ref"), str):
        node = resolve_pointer(doc, node["$ref"])
    out: list[dict] = []
    if not isinstance(node, dict):
        return out
    if isinstance(node.get("allOf"), list):
        for branch in node["allOf"]:
            out.extend(conjuncts(branch, doc))
    own = {k: v for k, v in node.items() if k != "allOf"}
    if own:
        out.append(own)
    return out


def reach(node: Any, tokens: list[str], doc: Any) -> list[Any]:
    if not tokens:
        return [node]
    tok = tokens[0]
    reached: list[Any] = []
    if tok == "[]":
        for conj in conjuncts(node, doc):
            if "items" in conj:
                reached.extend(reach(conj["items"], tokens[1:], doc))
    else:
        for conj in conjuncts(node, doc):
            props = conj.get("properties")
            if isinstance(props, dict) and tok in props:
                reached.extend(reach(props[tok], tokens[1:], doc))
    return reached


def parse_instance_path(path: str) -> list[str]:
    # "$.data.items[*].progress.completedAt" -> ["data","items","[]","progress","completedAt"]
    body = path[2:]
    tokens: list[str] = []
    for raw in body.split("."):
        if raw.endswith("[*]"):
            tokens.append(raw[:-3])
            tokens.append("[]")
        else:
            tokens.append(raw)
    return tokens


def response_schema(doc: Any, api: str) -> Any:
    path, method, status = API_ENDPOINT[api]
    return doc["paths"][path][method]["responses"][status]["content"]["application/json"]["schema"]


def field_errors(doc: Any, api: str, instance_path: str, value: Any) -> list:
    schema_node = reach(response_schema(doc, api), parse_instance_path(instance_path), doc)
    if not schema_node:
        raise AssertionError(f"{api} {instance_path}: schema not reachable")
    conv = {"allOf": [strict_convert(n, doc) for n in schema_node]}
    return sorted(
        Draft202012Validator(conv).iter_errors(value), key=lambda e: list(e.absolute_path)
    )


def a08_object_errors(doc: Any, data: dict) -> list:
    schema_node = reach(response_schema(doc, "A08"), parse_instance_path(A08_OBJECT_PATH), doc)
    if not schema_node:
        raise AssertionError("A08 $.data: schema not reachable")
    conv = {"allOf": [strict_convert(n, doc) for n in schema_node]}
    return sorted(
        Draft202012Validator(conv).iter_errors(data), key=lambda e: list(e.absolute_path)
    )


def main(argv: list[str]) -> int:
    expect_defects = "--expect-defects" in argv
    args = [a for a in argv if not a.startswith("--")]
    if len(args) != 1:
        print("usage: cc11_directed_strict_check.py <openapi.yaml> [--expect-defects]",
              file=sys.stderr)
        return 2
    doc = yaml.safe_load(open(args[0], encoding="utf-8").read())

    results = []  # (label, errors)

    # 12 nullable field paths: instance value is exactly null at that field
    for api, ipath in NULLABLE_CASES:
        errs = field_errors(doc, api, ipath, None)
        results.append((f"{api} {ipath} = null", errs))

    # A08 object: complete Progress + lastSyncedAt present
    base_data = {
        "completedCount": "0",
        "remainingCount": "0",
        "progressRevision": "0",
        "lastSyncedAt": "2026-09-10T04:00:00Z",
    }
    results.append(("A08 $.data {.., lastSyncedAt} present", a08_object_errors(doc, base_data)))
    # A08 object with completedAt:null too (union of both fixes)
    data_null_completed = dict(base_data, completedAt=None)
    results.append(("A08 $.data {completedAt:null, lastSyncedAt} present",
                    a08_object_errors(doc, data_null_completed)))

    ok = 0
    bad = 0
    print(f"mode: {'EXPECT-DEFECTS (pre-fix)' if expect_defects else 'EXPECT-CLEAN (post-fix)'}")
    for label, errs in results:
        if expect_defects:
            passed = bool(errs)  # pre-fix must reproduce an error
        else:
            passed = not errs  # post-fix must be clean
        tag = "ok  " if passed else "FAIL"
        detail = ""
        if errs:
            first = errs[0]
            detail = f" [{first.validator} @ {list(first.absolute_schema_path)}]"
        print(f"{tag} {label}{detail}")
        if passed:
            ok += 1
        else:
            bad += 1
    print(f"\n{ok} expectations met, {bad} failed (total {len(results)})")
    print("RESULT: " + ("PASS" if bad == 0 else "FAIL"))
    return 0 if bad == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

